INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gorgonia: A Gorgon''s Tragedy', 'Gorgonia: A Gorgon''s Tragedy is an RPG Maker horror game that reimagines the Gorgons’ origin story, offering a fresh perspective on the ancient myth. Step into the role of Medyuu, a beautiful lamia with unsettling secrets. Her sisters seem to glimpse something different in her—a haunting gaze that pulls her into a path of strange encounters and eerie discoveries.' FROM games WHERE igdb_id = 326975 ON CONFLICT (game_id, language_code) DO NOTHING;
