INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bricks Over Blocks', 'Bricks Over Blocks is a fast-paced 3D side-scroller blending platforming with brick-breaking mechanics. Smash bricks, dodge hazards, defend the blocks underfoot, and use power-ups to conquer challenging levels. It’s a fresh take on a classic genre. Are you ready to break through?' FROM games WHERE igdb_id = 338447 ON CONFLICT (game_id, language_code) DO NOTHING;
