INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-old-barn', 325287, '2024-09-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co954n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuqrl.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Old Barn', 'The Old Barn is a short, 10-minute narrative experience in the walking simulator genre. Explore a cosy, messy, and warm old barn and listen to the musings of the narrator as she recalls growing up in this environment. Relax while you navigate this highly detailed environment, listening to the soothing voice inviting to calm reflection and pondering of life''s learnings and mysteries. Take your time and see if you can spot any secret objects hiding in the clutter -- examining them from up close might reward you with a display of light. Can you spot all seven of them?' FROM games WHERE igdb_id = 325287 ON CONFLICT (game_id, language_code) DO NOTHING;
