INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cat-gets-medieval', 144972, '2024-04-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vzp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvur.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat Gets Medieval', 'Adventure like you''ve never adventured before! You get to be a cat. Not a ordinary cat, but a cat hero! Your kingdom had a great battle with an evil army. This evil army has fled and taken your King''s crown. The King needs you to fight all the evil forces and to bring back his crown to him . The only way to save the kingdom is to restore the crown to your King. You see his crown is a powerful artifact that helps the King protect the Kingdom. The King''s power is waning. You must hurry!! The evil army will be back and this time they will consume your kingdom into darkness. You don''t need to worry! You got this! As a Hero Cat you climb, jump, spit hairballs, scratch, and unlock powerful artifacts. The artifacts can be found if you are searching in the right places such as dungeons. It is a perilous journey ! Are you ready??' FROM games WHERE igdb_id = 144972 ON CONFLICT (game_id, language_code) DO NOTHING;
