INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frostpunk 2', 'Frostpunk 2 is the sequel to the highly acclaimed, BAFTA-nominated society survival game. The age of steam has passed and now, oil leads the way as humanity’s newest salvation. However, with new threats on the horizon, the future of the city looks even grimmer than before.' FROM games WHERE igdb_id = 164290 ON CONFLICT (game_id, language_code) DO NOTHING;
