INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Album', 'Shadow Album is a captivating narrative adventure game where you delve into the fragmented memories of Nira, piecing together her past through a collection of enigmatic photographs. Explore beautifully crafted environments, solve intricate puzzles, and unravel a compelling story filled with mystery and emotional depth. Experience a unique photographic memory mechanic as you reconstruct Nira''s history, one photo at a time.' FROM games WHERE igdb_id = 370393 ON CONFLICT (game_id, language_code) DO NOTHING;
