INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Revert', 'In Revert, use the time-manipulation powers granted to you by the Animal Spirits to solve over 40 puzzles in this puzzle-platformer. You start out with the ability to Save the state of the world, and Revert to go back to how it was. Solve puzzles with the world now reorganized! As you progress, unlock more time-manipulation powers to solve increasingly complex levels. Use your powers sparingly, and you’ll please the Animal Spirits.' FROM games WHERE igdb_id = 320242 ON CONFLICT (game_id, language_code) DO NOTHING;
