INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SokoNature', 'SokoNature is a Sokoban-inspired game with a unique twist. The character and blocks come in three sizes, each interacting differently. Small characters can''t push medium or large blocks, while large characters can push all sizes, with larger blocks moving fewer spaces. The game centers on saving the forest from fires, adding a thematic layer to the puzzle-solving mechanics.' FROM games WHERE igdb_id = 324666 ON CONFLICT (game_id, language_code) DO NOTHING;
