INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Butterfly//Circuit', 'Glimmers of hope are hard to come by, so what happens when the one you have is suddenly snuffed out? In the dark recesses of the city, just out of sight, silhouettes come in to view and connections start to form. Butterfly//Circuit is a cyberpunk thriller kinetic visual novel.' FROM games WHERE igdb_id = 252234 ON CONFLICT (game_id, language_code) DO NOTHING;
