INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sexy Memory Puzzle: Futanari Pool', 'Solve the puzzles to reveal and collect pictures of futanari characters having fun, sex and relaxing by a luxurious pool on the seaside, in images hidden behind pairs of cards which you have to match. Flip two cards, and if the numbers on them match, they will be removed, revealing a unique image.' FROM games WHERE igdb_id = 340619 ON CONFLICT (game_id, language_code) DO NOTHING;
