INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starship Troopers: Extermination', 'Starship Troopers: Extermination drops up to 16 players right into the fight against the Bug menace in this co-op first person shooter. Suit up and ship out to a far-off front as a Trooper in the Deep Space Vanguard, an elite Special Forces group within the Mobile Infantry. It’s up to squads like yours to battle against hundreds of bloodthirsty insectoid aliens and take back fallen colonies for the Federation. The only good Bug is a dead Bug!' FROM games WHERE igdb_id = 228175 ON CONFLICT (game_id, language_code) DO NOTHING;
