INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation: Polygon Storm', 'A fastpaced, military tug-of-war game with minimal micromanagement. Choose and deploy from a mix of specialized military units to overwhelm the enemy. Experiment with a huge variety of unit compositions, synergies, abilities, and upgrades to lead your army to victory!' FROM games WHERE igdb_id = 239775 ON CONFLICT (game_id, language_code) DO NOTHING;
