INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alaloth: Champions of the Four Kingdoms', 'Set in a vibrant fantasy world, Alaloth – Champions of The Four Kingdoms offers fast paced action with a deep narrative, developed by a team of industry veterans. The game brings the aRPG dynamics to a new level with a skill based gameplay inspired by great classics such as Moonstone and modern masterpieces as Dark Souls in a gritty, dark, mature environment filled with blood and magic!' FROM games WHERE igdb_id = 27406 ON CONFLICT (game_id, language_code) DO NOTHING;
