INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flowstone Saga', 'Flowstone Saga is a grand JRPG-inspired adventure that sports a unique battle system, where players manipulate falling blocks to defeat enemies in either real-time or turn-based combat. It features a wide variety of handcrafted and highly-detailed locations with meticulous pixel art and a soundtrack consisting of over 70 pieces, many of which feature live musicians.' FROM games WHERE igdb_id = 152329 ON CONFLICT (game_id, language_code) DO NOTHING;
