INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Like a Dragon: Infinite Wealth', 'Like a Dragon: Infinite Wealth is a turn-based role-playing game developed by Ryu Ga Gotoku Studio and published by Sega. It follows dual protagonists Ichiban Kasuga and Kazuma Kiryu, with the narrative set primarily in Japan and Hawaii. The game uses a party-based combat system that builds on previous Like a Dragon entries, incorporating positioning and environmental interactions. Players engage in main story missions alongside a wide range of optional activities and side content. The title combines narrative-driven progression with exploration, character development, and minigames typical of the series.' FROM games WHERE igdb_id = 217623 ON CONFLICT (game_id, language_code) DO NOTHING;
