INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Under the Red Sky', 'Under The Red Sky is a 3D parkour game where speed is king! Your goal is to get to the end of each level as quick as possible by taking one of the many different routes possible, or by finding your own. Watch out though, this isn''t all fun and games. You may accidentally fall into the past and uncover what happened and how to get back above. You may find that you''re now Under the Red Sky.' FROM games WHERE igdb_id = 358253 ON CONFLICT (game_id, language_code) DO NOTHING;
