INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('teppo-and-the-secret-ancient-city', 283231, '2024-01-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nef.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2pdf.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teppo and The Secret Ancient City', '"Teppo and The Secret Ancient City" is an exciting adventure where players take on the role of explorer Teppo, searching for the legendary stone fortress hidden in the Amazon jungle. Meeting the mysterious Tanaca Wanax, the last chief of the unknown tribe of elected allies, Ugha Lulala, players will discover the incredible and fantastic history of a highly evolved ancient civilization, superior to that of the Mayas and the Incas. With the help of unknown technologies from space visitors, including magical diamond-shaped stones that can open a portal to access parallel worlds, players will have to overcome obstacles and challenges to reach the fortress and open the first portal. A mystery and discovery filled adventure for fans of exploration and archaeology.' FROM games WHERE igdb_id = 283231 ON CONFLICT (game_id, language_code) DO NOTHING;
