INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pantheon: Rise of the Fallen', 'Pantheon: Rise of the Fallen is a group-focused MMORPG based on challenging gameplay and open world high fantasy. It takes place in a world populated by deities and heroes, called Terminus. Join the denizens of Terminus to uncover the mysteries of a world divided by Celestial loyalty… and betrayal. Make strong allies, or even stronger foes while you explore a captivating landscape that has its own stories to tell.' FROM games WHERE igdb_id = 75421 ON CONFLICT (game_id, language_code) DO NOTHING;
