INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poker Poker Magic', 'Embark on a magical journey with Caroline and Clovis in "Poker Poker Magic," a delightful 1v1 puzzle/action game for Playdate. Join Caroline, a spirited yet somewhat absent-minded magician-in-training, and her trusty dove, Ceres, as they set out to find a magical hat that could help Caroline ace her end-of-year exams at the Robert Houdin School of Prestidigitation. Little do they know, their adventure will lead them into a whimsical forest filled with colorful characters, including a clown, a four-eared rabbit, and a horse prince, each providing opportunities for thrilling magical duels.' FROM games WHERE igdb_id = 309027 ON CONFLICT (game_id, language_code) DO NOTHING;
