INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indus Battle Royale', 'Welcome to Indus, an Indo-Futuristic Battle Royale featuring a next-gen tactical battle royale experience, a never-before-seen Grudge feature, a unique Cosmium win condition, groundbreaking Avatars, deep lore, immersive graphics, and more in TPS/FPS battle royale mobile gaming. Join our Open Beta and step into the world of Virlok, where your gameplay experience will help shape the future of Indus. Be limitless. Be a Mythwalker. Crafted in India for the World' FROM games WHERE igdb_id = 234435 ON CONFLICT (game_id, language_code) DO NOTHING;
